t.script:
(function() {
    var STORAGE_KEY = 'misa_sale_status_code';
    var PAGE_SIZE = 50;
    var COLORS = {missing: '#d03b3b', requested: '#fab219', exception: '#9a9992', invoiced: '#0ca30c'};
    var STATE_META = [
        {key: 'missing', label: 'Chưa có đề nghị'},
        {key: 'requested', label: 'Đã đề nghị, chờ HĐ'},
        {key: 'exception', label: 'Ngoại lệ'},
        {key: 'invoiced', label: 'Đã xuất HĐ'},
    ];
    var state = {
        salerCode: localStorage.getItem(STORAGE_KEY) || '',
        search: '', stateFilter: '', dateFrom: '', dateTo: '',
        multiOrderGroup: false, multiRequest: false,
        page: 1, total: 0, rows: [], selected: {},
    };

    function esc(s) {
        var d = document.createElement('div');
        d.textContent = s == null ? '' : String(s);
        return d.innerHTML;
    }
    function fmtMoney(n) {
        if (!n) { return '0 đ'; }
        return Math.round(n).toLocaleString('vi-VN') + ' đ';
    }
    function fmtCompactMoney(n) {
        n = n || 0;
        if (Math.abs(n) >= 1000000) { return (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'tr'; }
        if (Math.abs(n) >= 1000) { return Math.round(n / 1000) + 'k'; }
        return String(Math.round(n));
    }
    function rpc(url, params) {
        return fetch(url, {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params || {}}),
        }).then(function(r) { return r.json(); }).then(function(j) {
            if (j.error) {
                var msg = (j.error.data && j.error.data.message) || j.error.message || 'Có lỗi xảy ra';
                throw new Error(msg);
            }
            if (j.result && j.result.status === 'error') {
                throw new Error(j.result.message || 'Có lỗi xảy ra');
            }
            return j.result;
        });
    }
    function toast(message, type) {
        var stack = document.getElementById('msu-toast-stack');
        var el = document.createElement('div');
        el.className = 'msu-toast' + (type ? ' ' + type : '');
        el.textContent = message;
        stack.appendChild(el);
        setTimeout(function() { el.remove(); }, 5000);
    }

    var selectEl = document.getElementById('msu-saler-select');
    var appEl = document.getElementById('msu-app');
    var hintEl = document.getElementById('msu-identity-hint');

    function loadSalerCodes() {
        return rpc('/misa_sale_status/api/saler_codes').then(function(res) {
            var codes = res.codes || [];
            codes.forEach(function(code) {
                var opt = document.createElement('option');
                opt.value = code;
                opt.textContent = code;
                selectEl.appendChild(opt);
            });
            if (state.salerCode && codes.indexOf(state.salerCode) !== -1) {
                selectEl.value = state.salerCode;
                onSalerChosen();
            } else if (state.salerCode) {
                hintEl.textContent = 'Mã "' + state.salerCode + '" đã lưu trước đó không còn hợp lệ, vui lòng chọn lại.';
                state.salerCode = '';
                localStorage.removeItem(STORAGE_KEY);
            }
        }).catch(function(e) { toast('Lỗi tải danh sách mã sale: ' + e.message, 'error'); });
    }

    function onSalerChosen() {
        appEl.style.display = state.salerCode ? '' : 'none';
        hintEl.textContent = '';
        if (state.salerCode) {
            loadList(1);
            loadDailyChart();
        }
    }

    selectEl.addEventListener('change', function() {
        state.salerCode = selectEl.value;
        state.selected = {};
        if (state.salerCode) {
            localStorage.setItem(STORAGE_KEY, state.salerCode);
        } else {
            localStorage.removeItem(STORAGE_KEY);
        }
        onSalerChosen();
    });

    function rowMeta(row) {
        var parts = [];
        if (row.multi_order_group) { parts.push('<i class="fa fa-sitemap msu-link-icon" title="Gộp chung nhiều đơn bán: ' + esc(row.group_order_names) + '"></i>'); }
        if (row.master_picking_id || (row.covered_pickings && row.covered_pickings.length)) { parts.push('<i class="fa fa-link msu-link-icon" title="Gộp chung đề nghị xuất HĐ với phiếu khác"></i>'); }
        return parts.join('');
    }

    function renderRows() {
        var tbody = document.getElementById('msu-tbody');
        tbody.innerHTML = '';
        document.getElementById('msu-empty').style.display = state.rows.length ? 'none' : '';
        state.rows.forEach(function(row) {
            var tr = document.createElement('tr');
            var checked = state.selected[row.id] ? 'checked="checked"' : '';
            var manualHtml = row.manual_refno
                ? '<span class="msu-manual-refno" title="Đã gắn mã đề nghị thủ công">' + esc(row.manual_refno) + '</span>'
                : '<span class="msu-muted">—</span>';
            var exceptionHtml = row.exception
                ? '<span class="msu-badge-exception" title="' + esc(row.exception_reason || '') + '">Ngoại lệ</span>' : '';
            var diffClass = row.amount_mismatch ? ' msu-col-diff-bad' : '';
            var diffHtml = row.state === 'invoiced'
                ? '<span class="' + diffClass.trim() + '">' + fmtMoney(row.amount_diff) + '</span>'
                : '<span class="msu-muted">—</span>';
            var coveredHtml = (row.covered_pickings && row.covered_pickings.length)
                ? esc(row.covered_pickings.map(function(c) { return c.name; }).join(', '))
                : '<span class="msu-muted">—</span>';
            tr.innerHTML =
                '<td><input type="checkbox" class="msu-row-check" data-id="' + row.id + '" ' + checked + '/></td>' +
                '<td><span class="msu-picking-name">' + esc(row.name) + '</span>' + rowMeta(row) + '<span class="msu-picking-order">' + esc(row.sale_order_name || '') + '</span></td>' +
                '<td>' + esc(row.partner_name) + '</td>' +
                '<td>' + esc(row.date_done) + '</td>' +
                '<td class="msu-col-num">' + fmtMoney(row.actual_amount) + '</td>' +
                '<td><span class="msu-badge-state msu-badge-state-' + row.state + '">' + esc(row.state_label) + '</span>' + exceptionHtml + '</td>' +
                '<td>' + (row.invoice_no ? esc(row.invoice_no) : '<span class="msu-muted">—</span>') + '</td>' +
                '<td class="msu-col-num">' + (row.state === 'invoiced' ? fmtMoney(row.invoice_amount) : '<span class="msu-muted">—</span>') + '</td>' +
                '<td class="msu-col-num">' + diffHtml + '</td>' +
                '<td>' + (row.master_picking_name ? esc(row.master_picking_name) : '<span class="msu-muted">—</span>') + '</td>' +
                '<td>' + coveredHtml + '</td>' +
                '<td>' + (row.multi_order_group ? esc(row.group_order_names || '') : '<span class="msu-muted">—</span>') + '</td>' +
                '<td>' + manualHtml + '</td>' +
                '<td><div class="msu-btn-group">' +
                    '<button class="msu-btn msu-btn-outline-primary msu-btn-xs msu-act-check" data-id="' + row.id + '" title="Kiểm tra ngay"><i class="fa fa-refresh"></i></button>' +
                    (row.state !== 'invoiced' ? '<button class="msu-btn msu-btn-outline-muted msu-btn-xs msu-act-link" data-id="' + row.id + '" data-name="' + esc(row.name) + '" title="Gắn mã đề nghị"><i class="fa fa-pencil"></i></button>' : '') +
                    (row.state !== 'invoiced' && !row.exception ? '<button class="msu-btn msu-btn-outline-danger msu-btn-xs msu-act-exception" data-id="' + row.id + '" data-name="' + esc(row.name) + '" title="Đánh dấu ngoại lệ"><i class="fa fa-ban"></i></button>' : '') +
                    (row.exception ? '<button class="msu-btn msu-btn-outline-muted msu-btn-xs msu-act-unexception" data-id="' + row.id + '" title="Bỏ ngoại lệ"><i class="fa fa-undo"></i></button>' : '') +
                '</div></td>';
            tbody.appendChild(tr);
        });
        bindRowEvents();
        updateBulkBar();
    }

    var lastCounts = {missing: 0, requested: 0, exception: 0, invoiced: 0};

    function updateStats(counts) {
        counts = counts || {};
        lastCounts = counts;
        document.getElementById('msu-count-missing').textContent = counts.missing || 0;
        document.getElementById('msu-count-requested').textContent = counts.requested || 0;
        document.getElementById('msu-count-exception').textContent = counts.exception || 0;
        document.getElementById('msu-count-invoiced').textContent = counts.invoiced || 0;
        renderDonut(counts);
    }

    // ===== Donut chart (cơ cấu trạng thái) — SVG vẽ tay, không cần thư viện =====
    function renderDonut(counts) {
        var container = document.getElementById('msu-donut-container');
        var total = STATE_META.reduce(function(sum, m) { return sum + (counts[m.key] || 0); }, 0);
        if (!total) {
            container.innerHTML = '<div class="msu-empty-chart">Chưa có dữ liệu trong phạm vi đang lọc.</div>';
            return;
        }
        var size = 148, r = 58, cx = size / 2, cy = size / 2, thickness = 20;
        var circumference = 2 * Math.PI * r;
        var gap = 3; // khoảng hở (đơn vị theo chu vi) giữa 2 lát, mô phỏng surface gap
        var offset = 0;
        var segments = [];
        STATE_META.forEach(function(meta) {
            var value = counts[meta.key] || 0;
            if (!value) { return; }
            var len = (value / total) * circumference;
            segments.push({
                meta: meta, value: value,
                dasharray: Math.max(len - gap, 0) + ' ' + (circumference - Math.max(len - gap, 0)),
                dashoffset: -offset,
            });
            offset += len;
        });
        var svgParts = ['<svg class="msu-donut-svg" width="' + size + '" height="' + size + '" viewBox="0 0 ' + size + ' ' + size + '">'];
        svgParts.push('<circle cx="' + cx + '" cy="' + cy + '" r="' + r + '" fill="none" stroke="#f1f0eb" stroke-width="' + thickness + '"/>');
        segments.forEach(function(seg) {
            svgParts.push(
                '<circle cx="' + cx + '" cy="' + cy + '" r="' + r + '" fill="none" stroke="' + COLORS[seg.meta.key] + '" ' +
                'stroke-width="' + thickness + '" stroke-dasharray="' + seg.dasharray + '" stroke-dashoffset="' + seg.dashoffset + '" ' +
                'transform="rotate(-90 ' + cx + ' ' + cy + ')" stroke-linecap="butt">' +
                '<title>' + esc(seg.meta.label) + ': ' + seg.value + ' phiếu</title>' +
                '</circle>'
            );
        });
        svgParts.push('<text x="' + cx + '" y="' + (cy - 4) + '" text-anchor="middle" class="msu-donut-hole-total">' + total + '</text>');
        svgParts.push('<text x="' + cx + '" y="' + (cy + 14) + '" text-anchor="middle" class="msu-donut-hole-label">TỔNG SỐ</text>');
        svgParts.push('</svg>');

        var legendParts = ['<div class="msu-legend">'];
        STATE_META.forEach(function(meta) {
            var value = counts[meta.key] || 0;
            var pct = total ? Math.round((value / total) * 100) : 0;
            legendParts.push(
                '<div class="msu-legend-row">' +
                    '<span class="msu-legend-dot" style="background:' + COLORS[meta.key] + '"></span>' +
                    '<span class="msu-legend-label">' + esc(meta.label) + '</span>' +
                    '<span class="msu-legend-value">' + value + '</span>' +
                    '<span class="msu-muted">(' + pct + '%)</span>' +
                '</div>'
            );
        });
        legendParts.push('</div>');

        container.innerHTML = '<div class="msu-donut-wrap">' + svgParts.join('') + legendParts.join('') + '</div>';
    }

    // ===== Bar + line chart (tiền xuất kho vs tiền đã xuất HĐ theo ngày) =====
    function renderBarChart(buckets) {
        var container = document.getElementById('msu-bar-chart-container');
        if (!buckets || !buckets.length) {
            container.innerHTML = '<div class="msu-empty-chart">Chưa có dữ liệu trong phạm vi đang lọc.</div>';
            return;
        }
        var width = Math.max(container.clientWidth || 560, 320);
        var height = 220;
        var padL = 54, padR = 14, padT = 14, padB = 28;
        var plotW = width - padL - padR, plotH = height - padT - padB;
        var maxVal = 0;
        buckets.forEach(function(b) { maxVal = Math.max(maxVal, b.actual_amount || 0, b.invoice_amount || 0); });
        if (!maxVal) { maxVal = 1; }
        // Làm tròn trục Y lên mốc đẹp (1/2/5 * 10^n) để nhãn dễ đọc.
        var niceMax = (function() {
            var exp = Math.floor(Math.log10(maxVal));
            var base = Math.pow(10, exp);
            var mult = maxVal / base;
            var steps = [1, 2, 2.5, 5, 10];
            for (var i = 0; i < steps.length; i++) { if (mult <= steps[i]) { return steps[i] * base; } }
            return 10 * base;
        })();
        var n = buckets.length;
        var slot = plotW / n;
        var barW = Math.min(24, slot * 0.44);

        function yFor(v) { return padT + plotH - (v / niceMax) * plotH; }
        function xCenter(i) { return padL + slot * i + slot / 2; }

        var ticks = 4;
        var gridParts = [];
        var yLabelParts = [];
        for (var t = 0; t <= ticks; t++) {
            var val = (niceMax / ticks) * t;
            var y = yFor(val);
            gridParts.push('<line x1="' + padL + '" y1="' + y + '" x2="' + (width - padR) + '" y2="' + y + '" stroke="#eceae4" stroke-width="1"/>');
            yLabelParts.push('<text x="' + (padL - 8) + '" y="' + (y + 3) + '" text-anchor="end" font-size="10" fill="#8b8d94">' + fmtCompactMoney(val) + '</text>');
        }

        // Nhãn trục X chọn lọc: ước lượng bề rộng cần cho 1 nhãn rồi chỉ hiện
        // đủ số nhãn vừa khít, tránh chữ đè lên nhau khi có nhiều cột (nhiều
        // tuần/ngày) — luôn hiện nhãn cuối cùng để biết mốc gần nhất.
        var minLabelWidth = 64;
        var maxLabels = Math.max(1, Math.floor(plotW / minLabelWidth));
        var labelStep = Math.max(1, Math.ceil(n / maxLabels));

        var barParts = [], dotParts = [], labelParts = [];
        var linePoints = [];
        buckets.forEach(function(b, i) {
            var cx = xCenter(i);
            var barX = cx - barW / 2;
            var barY = yFor(b.actual_amount || 0);
            var barH = Math.max(padT + plotH - barY, 0);
            if (barH > 0) {
                barParts.push(
                    '<rect x="' + barX + '" y="' + barY + '" width="' + barW + '" height="' + barH + '" rx="4" ry="4" fill="#2a78d6">' +
                    '<title>' + esc(b.label) + ' — Tiền xuất kho: ' + fmtMoney(b.actual_amount) + '</title>' +
                    '</rect>'
                );
            }
            var ly = yFor(b.invoice_amount || 0);
            linePoints.push(cx + ',' + ly);
            dotParts.push(
                '<circle cx="' + cx + '" cy="' + ly + '" r="4" fill="#0ca30c" stroke="#fff" stroke-width="2">' +
                '<title>' + esc(b.label) + ' — Tiền đã xuất HĐ: ' + fmtMoney(b.invoice_amount) + '</title>' +
                '</circle>'
            );
            if (i % labelStep === 0 || i === n - 1) {
                labelParts.push('<text x="' + cx + '" y="' + (height - 8) + '" text-anchor="middle" font-size="9" fill="#8b8d94">' + esc(b.label) + '</text>');
            }
        });

        var svg =
            '<svg width="100%" height="' + height + '" viewBox="0 0 ' + width + ' ' + height + '" preserveAspectRatio="xMidYMid meet">' +
            gridParts.join('') + yLabelParts.join('') +
            '<line x1="' + padL + '" y1="' + (padT + plotH) + '" x2="' + (width - padR) + '" y2="' + (padT + plotH) + '" stroke="#c9c8c1" stroke-width="1"/>' +
            barParts.join('') +
            '<polyline points="' + linePoints.join(' ') + '" fill="none" stroke="#0ca30c" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>' +
            dotParts.join('') + labelParts.join('') +
            '</svg>';
        container.innerHTML = svg;
    }

    function loadDailyChart() {
        if (!state.salerCode) { return; }
        var weekly = !state.dateFrom && !state.dateTo;
        document.getElementById('msu-chart-subtitle').textContent = weekly
            ? 'Theo tuần (không giới hạn ngày — chọn khoảng ngày để xem theo ngày)'
            : 'Theo ngày, trong khoảng đã chọn';
        rpc('/misa_sale_status/api/daily_stats', {
            saler_code: state.salerCode, date_from: state.dateFrom, date_to: state.dateTo, weekly: weekly,
        }).then(function(res) {
            renderBarChart(res.buckets || []);
        }).catch(function(e) { toast('Lỗi tải biểu đồ theo ngày: ' + e.message, 'error'); });
    }

    function updatePagination() {
        var totalPages = Math.max(1, Math.ceil(state.total / PAGE_SIZE));
        var pag = document.getElementById('msu-pagination');
        pag.style.display = state.total > PAGE_SIZE ? '' : 'none';
        document.getElementById('msu-page-label').textContent = 'Trang ' + state.page + ' / ' + totalPages + ' (' + state.total + ' phiếu)';
        document.getElementById('msu-prev').disabled = state.page <= 1;
        document.getElementById('msu-next').disabled = state.page >= totalPages;
    }

    function loadList(page, opts) {
        opts = opts || {};
        if (!state.salerCode) { return Promise.resolve(); }
        state.page = page;
        return rpc('/misa_sale_status/api/list', {
            saler_code: state.salerCode, search: state.search, state: state.stateFilter,
            date_from: state.dateFrom, date_to: state.dateTo,
            multi_order_group: state.multiOrderGroup, multi_request: state.multiRequest,
            limit: PAGE_SIZE, offset: (page - 1) * PAGE_SIZE,
        }).then(function(res) {
            var data = res.data || {};
            state.rows = data.rows || [];
            state.total = data.total || 0;
            state.selected = {};
            updateStats(data.counts);
            renderRows();
            updatePagination();
        }).catch(function(e) {
            if (!opts.silent) { toast('Lỗi tải danh sách: ' + e.message, 'error'); }
        });
    }

    document.getElementById('msu-search-btn').addEventListener('click', function() {
        state.search = document.getElementById('msu-search').value.trim();
        document.getElementById('msu-search-clear').style.display = state.search ? '' : 'none';
        loadList(1);
    });
    document.getElementById('msu-search').addEventListener('keydown', function(ev) {
        if (ev.key === 'Enter') { document.getElementById('msu-search-btn').click(); }
    });
    document.getElementById('msu-search-clear').addEventListener('click', function() {
        state.search = '';
        document.getElementById('msu-search').value = '';
        this.style.display = 'none';
        loadList(1);
    });
    document.getElementById('msu-state-select').addEventListener('change', function() {
        state.stateFilter = this.value;
        loadList(1);
    });
    document.getElementById('msu-multi-order-group').addEventListener('change', function() {
        state.multiOrderGroup = this.checked;
        loadList(1);
    });
    document.getElementById('msu-multi-request').addEventListener('change', function() {
        state.multiRequest = this.checked;
        loadList(1);
    });
    document.getElementById('msu-date-from').addEventListener('change', function() {
        state.dateFrom = this.value;
        document.getElementById('msu-date-clear').style.display = (state.dateFrom || state.dateTo) ? '' : 'none';
        loadList(1);
        loadDailyChart();
    });
    document.getElementById('msu-date-to').addEventListener('change', function() {
        state.dateTo = this.value;
        document.getElementById('msu-date-clear').style.display = (state.dateFrom || state.dateTo) ? '' : 'none';
        loadList(1);
        loadDailyChart();
    });
    document.getElementById('msu-date-clear').addEventListener('click', function() {
        state.dateFrom = ''; state.dateTo = '';
        document.getElementById('msu-date-from').value = '';
        document.getElementById('msu-date-to').value = '';
        this.style.display = 'none';
        loadList(1);
        loadDailyChart();
    });
    document.getElementById('msu-refresh-btn').addEventListener('click', function() {
        loadList(state.page);
        loadDailyChart();
    });
    document.getElementById('msu-prev').addEventListener('click', function() { if (state.page > 1) { loadList(state.page - 1); } });
    document.getElementById('msu-next').addEventListener('click', function() {
        if (state.page < Math.ceil(state.total / PAGE_SIZE)) { loadList(state.page + 1); }
    });

    document.getElementById('msu-select-all').addEventListener('change', function() {
        var checked = this.checked;
        state.rows.forEach(function(row) {
            if (checked) { state.selected[row.id] = true; } else { delete state.selected[row.id]; }
        });
        renderRows();
    });

    function bindRowEvents() {
        document.querySelectorAll('.msu-row-check').forEach(function(cb) {
            cb.addEventListener('change', function() {
                var id = parseInt(this.dataset.id, 10);
                if (this.checked) { state.selected[id] = true; } else { delete state.selected[id]; }
                updateBulkBar();
            });
        });
        document.querySelectorAll('.msu-act-check').forEach(function(btn) {
            btn.addEventListener('click', function() { runCheck([parseInt(this.dataset.id, 10)]); });
        });
        document.querySelectorAll('.msu-act-link').forEach(function(btn) {
            btn.addEventListener('click', function() { openLinkModal(parseInt(this.dataset.id, 10), this.dataset.name); });
        });
        document.querySelectorAll('.msu-act-exception').forEach(function(btn) {
            btn.addEventListener('click', function() { openExceptionModal([parseInt(this.dataset.id, 10)], this.dataset.name); });
        });
        document.querySelectorAll('.msu-act-unexception').forEach(function(btn) {
            btn.addEventListener('click', function() { runUnexception([parseInt(this.dataset.id, 10)]); });
        });
    }

    function updateBulkBar() {
        var ids = Object.keys(state.selected).map(Number);
        var bar = document.getElementById('msu-bulk-bar');
        bar.style.display = ids.length ? '' : 'none';
        document.getElementById('msu-bulk-count').textContent = 'Đã chọn ' + ids.length + ' phiếu';
    }

    function runCheck(ids) {
        rpc('/misa_sale_status/api/check', {picking_ids: ids, saler_code: state.salerCode}).then(function() {
            toast('Đã kiểm tra xong ' + ids.length + ' phiếu.', 'success');
            loadList(state.page);
            loadDailyChart();
        }).catch(function(e) { toast('Lỗi kiểm tra MISA: ' + e.message, 'error'); });
    }
    function runUnexception(ids) {
        rpc('/misa_sale_status/api/unmark_exception', {picking_ids: ids, saler_code: state.salerCode}).then(function() {
            toast('Đã bỏ đánh dấu ngoại lệ.', 'success');
            loadList(state.page);
        }).catch(function(e) { toast('Lỗi: ' + e.message, 'error'); });
    }

    document.getElementById('msu-bulk-check').addEventListener('click', function() { runCheck(Object.keys(state.selected).map(Number)); });
    document.getElementById('msu-bulk-unexception').addEventListener('click', function() { runUnexception(Object.keys(state.selected).map(Number)); });
    document.getElementById('msu-bulk-exception').addEventListener('click', function() {
        openExceptionModal(Object.keys(state.selected).map(Number), Object.keys(state.selected).length + ' phiếu đã chọn');
    });

    // ===== Modal: gắn mã đề nghị =====
    var linkModal = document.getElementById('msu-link-modal');
    var linkPickingId = null;
    function openLinkModal(id, name) {
        linkPickingId = id;
        document.getElementById('msu-link-picking-name').textContent = name;
        document.getElementById('msu-link-refno').value = '';
        document.getElementById('msu-link-error').textContent = '';
        linkModal.style.display = 'flex';
    }
    document.getElementById('msu-link-cancel').addEventListener('click', function() { linkModal.style.display = 'none'; });
    document.getElementById('msu-link-confirm').addEventListener('click', function() {
        var refno = document.getElementById('msu-link-refno').value.trim();
        var errEl = document.getElementById('msu-link-error');
        if (!refno) { errEl.textContent = 'Vui lòng nhập mã đề nghị.'; return; }
        rpc('/misa_sale_status/api/manual_link', {picking_id: linkPickingId, saler_code: state.salerCode, refno: refno}).then(function(res) {
            linkModal.style.display = 'none';
            if (res.warning) { toast(res.warning, 'warning'); } else { toast('Đã gắn mã đề nghị và xác nhận đã xuất hóa đơn.', 'success'); }
            loadList(state.page);
            loadDailyChart();
        }).catch(function(e) { errEl.textContent = e.message; });
    });

    // ===== Modal: đánh dấu ngoại lệ =====
    var exceptionModal = document.getElementById('msu-exception-modal');
    var exceptionIds = [];
    function openExceptionModal(ids, label) {
        exceptionIds = ids;
        document.getElementById('msu-exception-target').textContent = 'Phiếu: ' + label;
        document.getElementById('msu-exception-reason').value = '';
        document.getElementById('msu-exception-error').textContent = '';
        exceptionModal.style.display = 'flex';
    }
    document.getElementById('msu-exception-cancel').addEventListener('click', function() { exceptionModal.style.display = 'none'; });
    document.getElementById('msu-exception-confirm').addEventListener('click', function() {
        var reason = document.getElementById('msu-exception-reason').value.trim();
        var errEl = document.getElementById('msu-exception-error');
        if (!reason) { errEl.textContent = 'Vui lòng nhập lý do.'; return; }
        rpc('/misa_sale_status/api/mark_exception', {picking_ids: exceptionIds, saler_code: state.salerCode, reason: reason}).then(function() {
            exceptionModal.style.display = 'none';
            toast('Đã đánh dấu ngoại lệ.', 'success');
            loadList(state.page);
        }).catch(function(e) { errEl.textContent = e.message; });
    });

    window.addEventListener('resize', function() {
        if (state.salerCode) { loadDailyChart(); }
    });

    loadSalerCodes();
    // Cảnh báo trong trang: tự làm mới định kỳ để badge/đếm luôn cập nhật kể cả
    // khi sale không thao tác gì (đóng vai trò "cảnh báo" theo yêu cầu, không
    // cần push notification trình duyệt).
    setInterval(function() {
        if (state.salerCode) { loadList(state.page, {silent: true}); }
    }, 60000);
})();
